SELECT pl.id::text,pl.title,s.path source_path,pl.status,(pl.source_document_id IS NOT NULL AND (s.freshness_status IS DISTINCT FROM 'current' OR pl.source_revision_id IS DISTINCT FROM v.id)) is_stale,pl.updated_at::text FROM plans pl LEFT JOIN source_documents s ON s.id=pl.source_document_id LEFT JOIN document_revisions v ON v.source_document_id=s.id AND v.is_current WHERE pl.project_id=$1 AND pl.is_current LIMIT 1
